  async function importSubject(){const payload=pendingImport?.payload;if(!payload)return;let src=payload.schema==='gnosis-subject-v1'?payload:payload.subjects?.[0]||payload;const mode=$('[data-import-mode]')?.value||'new',mergeId=$('[data-merge-subject]')?.value,source=$('[data-import-source]')?.value||'Shared via Gnosis';let subject=mode==='merge'?data.subjects.find(s=>s.id===mergeId):null;if(!subject){subject={id:uid(),name:src.name||'Shared subject',color:0,concepts:[]};data.subjects.push(subject);}const photos=[];for(const original of src.concepts||[]){const concept={id:uid(),title:String(original.title||'Untitled'),notes:String(original.notes||''),terms:Array.isArray(original.terms)?original.terms.map(t=>({id:uid(),name:String(t.name||''),notes:String(t.notes||t.definition||'')})):[],chapter:original.chapter||'',misconceptions:Array.isArray(original.misconceptions)?original.misconceptions.map(String):[],customQuestions:Array.isArray(original.customQuestions)?original.customQuestions:[],source, schedule:null};subject.concepts.push(concept);for(const photo of original.photos||[]){if(typeof photo.base64==='string')photos.push({photoId:uid(),conceptId:concept.id,name:photo.name||'shared-photo.jpg',type:photo.type||'image/jpeg',blob:base64Blob(photo.base64,photo.type),createdAt:new Date().toISOString()});}}for(const photo of photos)await putPhoto(photo);selectedSubjectId=subject.id;data.activeSubjectId=subject.id;persist();$('#app-dialog').close();pendingImport=null;view='subject';render();toast(`Imported ${src.concepts?.length||0} concepts.`);}
  async function importLibrary(){const payload=pendingImport?.payload;if(!payload)return;let imported=0;for(const sourceSubject of payload.subjects||[]){const subject={id:uid(),name:sourceSubject.name||'Imported subject',color:data.subjects.length%palettes.length,concepts:[]};data.subjects.push(subject);for(const original of sourceSubject.concepts||[]){const concept={id:uid(),title:String(original.title||'Untitled'),notes:String(original.notes||''),misconceptions:Array.isArray(original.misconceptions)?original.misconceptions.map(String):[],customQuestions:Array.isArray(original.customQuestions)?original.customQuestions:[],source:'Gnosis library backup',schedule:null,terms:Array.isArray(original.terms)?original.terms.map(t=>({id:uid(),name:String(t.name||''),notes:String(t.notes||t.definition||'')})):[]};subject.concepts.push(concept);imported++;for(const photo of original.photos||[]){if(typeof photo.base64==='string')await putPhoto({photoId:uid(),conceptId:concept.id,name:photo.name||'shared-photo.jpg',type:photo.type||'image/jpeg',blob:base64Blob(photo.base64,photo.type),createdAt:new Date().toISOString()});}}}selectedSubjectId=data.subjects[data.subjects.length-(payload.subjects||[]).length]?.id||data.subjects[0]?.id;data.activeSubjectId=selectedSubjectId;persist();$('#app-dialog').close();pendingImport=null;view='library';render();toast(`Imported ${imported} concepts from the library backup.`);}
  async function restoreBackup(){const payload=pendingImport?.payload;if(!payload||!confirm('Replace this device’s Gnosis library with the backup?'))return;await clearPhotos();loadedPhotos.clear();for(const subject of payload.subjects||[]){for(const concept of subject.concepts||[]){for(const photo of concept.photos||[]){if(typeof photo.base64==='string')await putPhoto({photoId:photo.id||uid(),conceptId:concept.id,name:photo.name||'photo.jpg',type:photo.type||'image/jpeg',blob:base64Blob(photo.base64,photo.type),createdAt:photo.createdAt||new Date().toISOString()});}}}data={...payload,version:2,subjects:(payload.subjects||[]).map(subject=>({...subject,concepts:(subject.concepts||[]).map(concept=>{const {photos,...saved}=concept;return{...saved,misconceptions:saved.misconceptions||[],customQuestions:saved.customQuestions||[],schedule:saved.schedule||null};})}))};selectedSubjectId=data.activeSubjectId||data.subjects[0]?.id;persist();$('#app-dialog').close();pendingImport=null;view='library';render();toast('Full backup restored.');}
  async function parseHash(){const match=location.hash.match(/^#gnosis=([A-Za-z0-9_-]+)$/);if(!match)return;try{const parsed=JSON.parse(await decompressString(match[1]));history.replaceState(null,'',location.pathname+location.search);showImportPreview(parsed,'link');}catch(error){history.replaceState(null,'',location.pathname+location.search);toast(error.message||'That share link could not be opened.');}}

  function handleChallengeResults(payload){const original=data.challengeHistory.find(item=>item.challengeId===payload.challengeId);openDialog(`<div class="eyebrow">STUDY BUDDY RESULTS</div><h2>${esc(payload.participant||'Your buddy')}</h2><div class="stats-grid"><div class="stat-card"><strong>${payload.score}/${payload.total}</strong><span>buddy score</span></div><div class="stat-card"><strong>${original?`${original.score}/${original.total}`:'—'}</strong><span>your score</span></div></div><p class="subtitle">${original?'Compare how you both did on the same fixed questions.':'This result is from a challenge not recorded in this library.'}</p><div class="dialog-actions"><button class="primary" data-action="close-dialog">Done</button></div>`);}
  async function exportChallenge(){const quiz=session?.finished?session:lastQuiz;if(!quiz?.questions?.length){toast('Finish a quiz first to create a challenge.');return;}const challengeId=uid(),photos=await allPhotos(),questions=[];for(const q of quiz.questions){const copy={qid:q.qid,prompt:q.prompt,type:q.type,conceptTitle:q.conceptTitle,sourceNote:q.sourceNote,correctText:q.correctText,highlight:q.highlight,options:q.options.map(option=>({...option,belongsTo:findConcept(option.conceptId)?.concept.title||''})),conceptId:q.conceptId};if(q.photoId){const photo=photos.find(p=>p.photoId===q.photoId);if(photo)copy.photo={name:photo.name,type:photo.type,base64:await blobBase64(photo.blob)};}questions.push(copy);}const challenge={schema:'gnosis-challenge-v1',challengeId,title:'Gnosis study buddy challenge',createdAt:new Date().toISOString(),questions};quiz.challengeId=challengeId;data.challengeHistory.push({challengeId,score:quiz.answers.filter(a=>a.correct).length,total:quiz.questions.length,name:'Me'});persist();await deliverFile('gnosis-study-challenge.gnosis',challenge);}
