  async function openTeachDialog(ref){openDialog(`<div class="eyebrow">TEACH-BACK · ${esc(ref.subject.name)}</div><h2>${esc(nameConcept(ref.concept))}</h2><label class="label">Explain it from memory</label><textarea class="textarea" data-teach-response placeholder="Write or say what you remember…"></textarea><div data-teach-reveal hidden><div class="feedback-columns"><section class="panel"><div class="label">YOUR EXPLANATION</div><p data-teach-your></p></section><section class="panel"><div class="label">ORIGINAL NOTES AND TERMS</div><p>${esc(ref.concept.notes||'No notes saved.')}</p>${ref.concept.terms?.length?`<div class="terms-checklist">${ref.concept.terms.map(t=>`<label class="row term-check"><input type="checkbox" data-term-hit><span><strong>${esc(t.name)}</strong><span class="small muted">${esc(t.notes)}</span></span></label>`).join('')}</div>`:''}<div class="photo-gallery" data-teach-gallery></div></section></div><div class="row" style="margin-top:12px"><button class="small-button" data-teach-rate="again">Needs work</button><button class="small-button" data-teach-rate="good">Got it</button></div></div><div class="dialog-actions"><button class="secondary" data-action="close-dialog">Close</button><button class="primary" data-action="reveal-teach" data-id="${esc(ref.concept.id)}">Reveal notes</button></div>`);}
  document.addEventListener('click',async event=>{const reveal=event.target.closest('[data-action="reveal-teach"]');if(reveal){const id=reveal.dataset.id;findConcept(id);$('[data-teach-your]').textContent=$('[data-teach-response]').value||'No explanation written.';$('[data-teach-response]').hidden=true;$('[data-teach-reveal]').hidden=false;reveal.hidden=true;const gallery=$('[data-teach-gallery]');for(const p of await photosFor(id))gallery.insertAdjacentHTML('beforeend',`<div class="photo-thumb-wrap"><img class="photo-thumb" src="${photoUrl(p)}" data-photo-view="${esc(p.photoId)}" alt="Concept photo"></div>`);return;}const rate=event.target.closest('[data-teach-rate]');if(rate){const id=$('[data-action="reveal-teach"]')?.dataset.id,ref=findConcept(id);if(ref){refreshSessionSchedule({conceptId:id},rate.dataset.teachRate==='good');ref.concept.selfRating=rate.dataset.teachRate;logStudy(2,[ref.subject.id]);persist();$('#app-dialog').close();toast(rate.dataset.teachRate==='good'?'Marked as understood.':'Marked for another look.');}return;}});

